begin
    DBMS_CLOUD.CREATE_CREDENTIAL(
                    credential_name => {#0},
                    username        => {#1},
                    password        => {#2});
end;

begin
    DBMS_CLOUD_AI.SET_ATTRIBUTES(
        PROFILE_NAME => {#0},
        ATTRIBUTES   => {#1});
end;

declare
    v_response CLOB;
begin
    v_response := DBMS_CLOUD_AI.GENERATE(
                        prompt       => {#3},
                        profile_name => {#0},
                        action       => {#1},
                        attributes   => {#2});
    ? := v_response;
end;

DECLARE
    v_prompt   CLOB;
    v_response CLOB;
BEGIN
WITH ranked AS (
    SELECT CONTENT
        FROM REPORTS_NO_WEEK rnw
        ORDER BY vector_distance(
                    rnw.EMBEDDING_TITLE,
                    vector_embedding(doc_model
                            USING {#0} AS data)
        ) ASC
    FETCH FIRST 5 ROWS ONLY
), prompt_text AS (
        SELECT LISTAGG(CONTENT, CHR(10))
        WITHIN GROUP (ORDER BY NULL) AS prompt
        FROM ranked
        )
SELECT prompt
        INTO v_prompt
        FROM prompt_text;

v_response := DBMS_VECTOR.UTL_TO_GENERATE_TEXT(
v_prompt,
    JSON({#1})
);

? := v_response;
END;

