begin
    DBMS_VECTOR.DROP_ONNX_MODEL(
            model_name => {#0});
end;

BEGIN
    EXECUTE IMMEDIATE '
        CREATE TABLE IF NOT EXISTS {0}.{1} (
            {2} VARCHAR(4000) PRIMARY KEY,
            {3} CLOB,
            {4} VECTOR(*, FLOAT32) NOT NULL,
            {5} JSON
        )
    ';
END;

INSERT INTO {0}
(id, file_content, metadata,file_hash,file_size)
VALUES ({#1}, EMPTY_BLOB(), {#2},{#3},{#4})

UPDATE {0}
SET file_content = {#1}
WHERE id = {#2}

BEGIN
    DBMS_VECTOR.LOAD_ONNX_MODEL({#0}, {#1});
END;

select
    CHUNK_OFFSET as "Chunk offset",
    CHUNK_LENGTH as "Chunk length",
    CHUNK_TEXT as "Chunk text"
from VECTOR_CHUNKS(
    {#0}
    BY {1}
    MAX {2}
    OVERLAP {3}
    SPLIT BY {4})
